package com.anysale.lead.tenant;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken; import org.springframework.stereotype.Component; import org.springframework.web.server.ResponseStatusException;
@Component public class TenantContext { private final boolean secured; private final String local; public TenantContext(@Value("${anysale.security.enabled:false}") boolean secured,@Value("${anysale.tenant.local-id:anysale}") String local){this.secured=secured;this.local=local;} public String tenantId(){Object a=SecurityContextHolder.getContext().getAuthentication();if(a instanceof JwtAuthenticationToken j){String t=j.getToken().getClaimAsString("tenant_id");if(t!=null&&t.matches("[a-z0-9][a-z0-9-]{0,62}"))return t;throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Missing or invalid tenant_id claim");}if(!secured)return local;throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authenticated tenant is required");}}
